import{_ as a,o as s,c as n,a2 as o}from"./chunks/framework.C4u7U0Dw.js";const h=JSON.parse('{"title":"第 2 章 第一次对话：把需求讲清楚","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md","filePath":"bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md"}'),e={name:"bluebook/第一篇 使用手册：先把我用起来/第 2 章 第一次对话：把需求讲清楚.md"};function d(l,t,p,r,i,c){return s(),n("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-2-章-第一次对话-把需求讲清楚" tabindex="-1">第 2 章 第一次对话：把需求讲清楚 <a class="header-anchor" href="#第-2-章-第一次对话-把需求讲清楚" aria-label="Permalink to &quot;第 2 章 第一次对话：把需求讲清楚&quot;">​</a></h1><blockquote><p>本章目标：掌握&quot;四要素任务描述法&quot;，学会把模糊想法变成可执行任务。这是全白皮书最重要的一章——<strong>提示词的质量，决定交付的质量</strong>。</p></blockquote><h2 id="_2-1-为什么-讲清楚-如此重要" tabindex="-1">2.1 为什么&quot;讲清楚&quot;如此重要 <a class="header-anchor" href="#_2-1-为什么-讲清楚-如此重要" aria-label="Permalink to &quot;2.1 为什么&quot;讲清楚&quot;如此重要&quot;">​</a></h2><p>同一个问题，两种问法，结果天差地别：</p><ul><li>❌ 模糊版：&quot;帮我把这个文档弄一下。&quot;</li><li>✅ 清晰版：&quot;请阅读 docs/report.md，把第三节的数据更新为 data/q3.csv 里的最新数据，并输出为 docs/report_v2.md。&quot;</li></ul><p>同样的我，前者只能猜，后者能一次做对。这不是玄学，而是<strong>信息论</strong>：你不给我验收标准，我就只能自己发明验收标准；你给的上下文越完整，我猜错的概率就越低。</p><h3 id="_2-1-1-模糊需求的三种典型后果" tabindex="-1">2.1.1 模糊需求的三种典型后果 <a class="header-anchor" href="#_2-1-1-模糊需求的三种典型后果" aria-label="Permalink to &quot;2.1.1 模糊需求的三种典型后果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模糊表达</th><th>我的实际反应</th><th>你得到的</th></tr></thead><tbody><tr><td>&quot;弄一下&quot;&quot;搞搞&quot;</td><td>猜测你的意图</td><td>大概率不是你想要的</td></tr><tr><td>只给目标不给输入</td><td>找不到数据，反复追问</td><td>时间浪费在来回确认</td></tr><tr><td>验收标准太虚（&quot;写好一点&quot;）</td><td>按我的审美默认执行</td><td>风格不符，推倒重来</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">核心认知</p><p><strong>讲清楚需求，不是麻烦我，而是帮助你自己。</strong> 一次说清，胜过十轮修改。高手和新手的差距，一半在&quot;会不会把需求说清楚&quot;。</p></div><h2 id="_2-2-四要素任务描述法" tabindex="-1">2.2 四要素任务描述法 <a class="header-anchor" href="#_2-2-四要素任务描述法" aria-label="Permalink to &quot;2.2 四要素任务描述法&quot;">​</a></h2><p>任何需求，都可以套进下面这个模板。四要素缺一不可：</p><table tabindex="0"><thead><tr><th>要素</th><th>要回答的问题</th><th>反例（模糊）</th><th>正例（清晰）</th></tr></thead><tbody><tr><td><strong>目标</strong></td><td>你要什么结果？</td><td>做份报告</td><td>一份 Q3 运营复盘报告</td></tr><tr><td><strong>输入</strong></td><td>资料在哪？</td><td>用我们的数据</td><td>data/q3.csv、docs/template.md</td></tr><tr><td><strong>约束</strong></td><td>有什么限制？</td><td>好看点</td><td>不超过 3 页、用中文、保留表格</td></tr><tr><td><strong>验收</strong></td><td>怎么算完成？</td><td>弄好就行</td><td>数据与 csv 一致，有结论有建议</td></tr></tbody></table><h3 id="_2-2-1-组合成一句话" tabindex="-1">2.2.1 组合成一句话 <a class="header-anchor" href="#_2-2-1-组合成一句话" aria-label="Permalink to &quot;2.2.1 组合成一句话&quot;">​</a></h3><p>把四要素写进一句话，就是：</p><blockquote><p>&quot;阅读 data/q3.csv 和 docs/template.md，生成一份<strong>中文 Q3 运营复盘</strong>（目标），<strong>不超过 3 页</strong>（约束），<strong>数据必须与 csv 一致</strong>（验收），最后给出 3 条建议。&quot;</p></blockquote><h3 id="_2-2-2-进阶-任务卡格式" tabindex="-1">2.2.2 进阶：任务卡格式 <a class="header-anchor" href="#_2-2-2-进阶-任务卡格式" aria-label="Permalink to &quot;2.2.2 进阶：任务卡格式&quot;">​</a></h3><p>复杂任务建议直接使用&quot;任务卡&quot;格式（附录 A 有完整模板）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>【任务卡】</span></span>
<span class="line"><span>任务名称：Q3 运营复盘</span></span>
<span class="line"><span>目标：输出一份不超过 3 页的中文复盘报告</span></span>
<span class="line"><span>输入：</span></span>
<span class="line"><span>  - 数据：data/q3.csv</span></span>
<span class="line"><span>  - 模板：docs/template.md</span></span>
<span class="line"><span>约束：中文、保留表格、结论放开头</span></span>
<span class="line"><span>验收：</span></span>
<span class="line"><span>  1. 数据与 q3.csv 完全一致</span></span>
<span class="line"><span>  2. 包含增长/留存两个板块</span></span>
<span class="line"><span>  3. 末尾给出 3 条可执行建议</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">为什么任务卡更可靠</p><p><strong>四要素适合口头对话，任务卡适合重要任务。</strong> 把验收标准逐条列出来，我就有了&quot;自检清单&quot;——交付前先自查，而不是等你发现错误。</p></div><h2 id="_2-3-一次成功的对话流程" tabindex="-1">2.3 一次成功的对话流程 <a class="header-anchor" href="#_2-3-一次成功的对话流程" aria-label="Permalink to &quot;2.3 一次成功的对话流程&quot;">​</a></h2><h3 id="_2-3-1-标准三步曲" tabindex="-1">2.3.1 标准三步曲 <a class="header-anchor" href="#_2-3-1-标准三步曲" aria-label="Permalink to &quot;2.3.1 标准三步曲&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：给任务（四要素尽量齐）</span></span>
<span class="line"><span>我：① 复述理解 → ② 指出缺信息（如果有）→ ③ 开始执行</span></span>
<span class="line"><span>你：检查中间产物，提出修改</span></span>
<span class="line"><span>我：修订 → 交付</span></span></code></pre></div><h3 id="_2-3-2-复述环节为什么不能省" tabindex="-1">2.3.2 复述环节为什么不能省 <a class="header-anchor" href="#_2-3-2-复述环节为什么不能省" aria-label="Permalink to &quot;2.3.2 复述环节为什么不能省&quot;">​</a></h3><p><strong>如果我的复述和你想要的不一致，立刻纠正我，不要让我一路错下去。</strong></p><p>举例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>你：写一份产品发布公告</span></span>
<span class="line"><span>我（复述）：我理解是——为「MomaWork 2.0」写一篇面向公众号的发布公告，</span></span>
<span class="line"><span>   包含新功能亮点、上线时间、下载方式，约 800 字，对吗？</span></span>
<span class="line"><span>你：不对，是给内部团队看的邮件，不是公众号。</span></span>
<span class="line"><span>我（修正）：明白了，改为内部邮件格式。</span></span></code></pre></div><p><strong>复述是免费的保险。</strong> 一次 30 秒的确认，可能省下 30 分钟的返工。</p><h2 id="_2-4-常见沟通误区与纠正" tabindex="-1">2.4 常见沟通误区与纠正 <a class="header-anchor" href="#_2-4-常见沟通误区与纠正" aria-label="Permalink to &quot;2.4 常见沟通误区与纠正&quot;">​</a></h2><table tabindex="0"><thead><tr><th>❌ 误区</th><th>为什么不行</th><th>✅ 正确做法</th></tr></thead><tbody><tr><td>一次丢太多任务：&quot;帮我做 A、B、C、D，还要 E&quot;</td><td>上下文太长，互相干扰，容易遗漏</td><td>拆开，一次一个，或明确优先级</td></tr><tr><td>只给目标不给输入：&quot;分析一下我们的销售&quot;</td><td>我没有数据源，只能瞎编</td><td>&quot;分析 data/sales.csv，按地区汇总&quot;</td></tr><tr><td>验收标准太虚：&quot;写好一点&quot;</td><td>标准无法检验</td><td>&quot;结构总分总，结论放开头，每条建议配数据&quot;</td></tr><tr><td>中途换需求：&quot;对了，顺便改成英文版&quot;</td><td>打乱执行中的上下文</td><td>先完成当前任务，再开新任务</td></tr><tr><td>不反馈直接重开：&quot;算了，重做&quot;</td><td>丢失了失败教训</td><td>告诉我哪里不对，我修正而不是重来</td></tr></tbody></table><h2 id="_2-5-指令模板速用" tabindex="-1">2.5 指令模板速用 <a class="header-anchor" href="#_2-5-指令模板速用" aria-label="Permalink to &quot;2.5 指令模板速用&quot;">​</a></h2><p>保存以下模板（或直接让我存进记忆系统，第 6 章会讲）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务：</span></span>
<span class="line"><span>目标：{你要的结果}</span></span>
<span class="line"><span>输入：{文件/目录/资料位置}</span></span>
<span class="line"><span>约束：{格式/长度/语言/风格}</span></span>
<span class="line"><span>验收：{怎么算完成，尽量列成清单}</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">使用建议</p><ul><li>简单任务：一句话说清四要素即可；</li><li>重要任务：用任务卡格式，验收列成清单；</li><li>复杂任务：先让我复述确认，再开始执行。</li></ul></div><h2 id="_2-6-进阶技巧-给-ai-好的示例" tabindex="-1">2.6 进阶技巧：给 AI&quot;好的示例&quot; <a class="header-anchor" href="#_2-6-进阶技巧-给-ai-好的示例" aria-label="Permalink to &quot;2.6 进阶技巧：给 AI&quot;好的示例&quot;&quot;">​</a></h2><p>有时&quot;讲清楚&quot;不如&quot;给样例&quot;。<strong>示例（few-shot）是最强的沟通方式</strong>：</p><table tabindex="0"><thead><tr><th>沟通方式</th><th>效果</th></tr></thead><tbody><tr><td>&quot;按我们公司的格式写&quot;</td><td>模糊，我要猜格式</td></tr><tr><td>&quot;按 docs/往期周报/2026-W31.md 的格式写&quot;</td><td>我可以读模板，精确模仿</td></tr><tr><td>&quot;这是上次的周报，这次按同样风格写&quot;</td><td>直接给参照物，最可靠</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">实践建议</p><p><strong>凡是&quot;有模板、有旧例、有参照&quot;的任务，一律把参照物指给我。</strong> 一个好的参照物胜过十句形容词。</p></div><h2 id="_2-7-本章练习" tabindex="-1">2.7 本章练习 <a class="header-anchor" href="#_2-7-本章练习" aria-label="Permalink to &quot;2.7 本章练习&quot;">​</a></h2><ol><li><strong>改写题</strong>：把&quot;帮我整理一下这些文件&quot;改写成四要素齐全的任务描述。</li><li><strong>实战题</strong>：用四要素模板，向我提出一个你手头的真实任务。</li><li><strong>校验题</strong>：让我复述一遍你的任务，检查理解是否一致；如有遗漏，补上再开始。</li><li><strong>示例题</strong>：找一个你过去写过的文档作为&quot;参照物&quot;，让我按它的风格生成一个新版本。</li></ol><hr><blockquote><p><strong>小结</strong>：需求表达 = 目标 + 输入 + 约束 + 验收。<strong>一次说清，胜过十轮修改</strong>；重要任务用任务卡，风格任务给参照物。下一章，我们看看我是怎么&quot;动手&quot;工作的——文件、命令与工具。</p></blockquote>`,41)])])}const q=a(e,[["render",d]]);export{h as __pageData,q as default};
